CREATE OR REPLACE FUNCTION pg_temp.concert_seed_insert(target_table text, payload jsonb)
RETURNS integer LANGUAGE plpgsql AS $insert$
DECLARE columns_sql text; identity_column text; inserted_id integer;
BEGIN
  IF target_table NOT IN ('events','event_images','ticket_types','refund_policies','seat_maps','seat_zones','event_gates','event_compliance_documents','event_compliance_reviews') THEN
    RAISE EXCEPTION 'Unsupported fixture table %', target_table;
  END IF;
  SELECT string_agg(format('%I',column_name),', ' ORDER BY ordinal_position)
    INTO columns_sql FROM information_schema.columns
    WHERE table_schema='public' AND table_name=target_table AND is_identity='NO'
      AND is_generated='NEVER' AND payload ? column_name;
  SELECT column_name INTO STRICT identity_column FROM information_schema.columns
    WHERE table_schema='public' AND table_name=target_table AND is_identity='YES';
  EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) RETURNING %I', target_table, columns_sql, columns_sql, target_table, identity_column)
    INTO inserted_id USING payload;
  RETURN inserted_id;
END;
$insert$;

